package com.mediassistrover.backend.service.impl;
import com.mediassistrover.backend.dto.common.DeletionContracts.*;import com.mediassistrover.backend.enums.JobStatus;import com.mediassistrover.backend.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.nio.ByteBuffer;import java.util.*;import java.util.UUID;
@Service @RequiredArgsConstructor public class JobHardDeleteService {private final JdbcTemplate jdbc;
 @Transactional(readOnly=true) public DeletionImpactResponse impact(UUID id){byte[]k=key(id);String s=status(k,id);var deps=new LinkedHashMap<String,Long>();deps.put("jobTasks",count("JobTask","job_id",k));deps.put("jobSteps",countJoin("JobStep","JobTask","job_task_id","job_id",k));deps.put("jobEvents",count("JobEvent","job_id",k));deps.put("commands",count("RobotCommandOutbox","job_id",k));deps.put("mappingSessions",count("MappingSession","job_id",k));deps.put("alerts",alerts(k));List<String>b=new ArrayList<>();if(!Set.of("SUCCEEDED","FAILED","CANCELLED").contains(s))b.add("Job status "+s+" is not terminal");if(count("Job","recovery_of_job_id",k)>0)b.add("Job has recovery Job");if(openMappings(k)>0)b.add("Job has an open mapping session");if(alerts(k)>0)b.add("Job has Alert; delete closed Alert first");return new DeletionImpactResponse(id,"Job",b.isEmpty(),b,Map.copyOf(deps));}
 @Transactional(propagation=Propagation.MANDATORY) public HardDeleteResponse delete(UUID id){byte[]k=key(id);lock(k,id);var i=impact(id);if(!i.canHardDelete())throw new ConflictException(String.join(", ",i.blockers()));var d=new LinkedHashMap<String,Long>();d.put("RobotOperationAuthorization",del("DELETE roa FROM RobotOperationAuthorization roa JOIN JobStep s ON roa.job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("MqttOperationRecoveryReceipt",del("DELETE r FROM MqttOperationRecoveryReceipt r JOIN JobStep s ON r.job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("JobStepResponse",del("DELETE r FROM JobStepResponse r JOIN JobStep s ON r.job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("JobNavigationSelectionsBySelector",del("DELETE n FROM JobNavigationSelection n JOIN JobStep s ON n.selector_job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("JobNavigationSelectionsByMove",del("DELETE n FROM JobNavigationSelection n JOIN JobStep s ON n.move_job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("JobNavigationSelectionsByResolve",del("DELETE n FROM JobNavigationSelection n JOIN JobStep s ON n.resolve_job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("AiObservation",del("DELETE a FROM AiObservation a JOIN JobStep s ON a.job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("CrowdDensityRecordUnlinked",del("UPDATE CrowdDensityRecord c JOIN JobStep s ON c.job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id SET c.job_step_id=NULL WHERE t.job_id=?",k));d.put("QrChallenge",del("DELETE FROM QrChallenge WHERE job_id=?",k));d.put("AuthVerification",del("DELETE FROM AuthVerification WHERE job_id=?",k));d.put("RobotCommandOutbox",del("DELETE FROM RobotCommandOutbox WHERE job_id=?",k));d.put("WorkflowOrchestrationWork",del("DELETE FROM WorkflowOrchestrationWork WHERE job_id=?",k));d.put("JobEvent",del("DELETE FROM JobEvent WHERE job_id=?",k));d.put("MapArtifact",del("DELETE a FROM MapArtifact a JOIN MappingSession s ON a.session_id=s.session_id WHERE s.job_id=?",k));d.put("MappingSession",del("DELETE FROM MappingSession WHERE job_id=?",k));d.put("RobotStatusHistoryUnlinked",del("UPDATE RobotStatusHistory SET job_id=NULL WHERE job_id=?",k));d.put("RobotLocationHistoryUnlinked",del("UPDATE RobotLocationHistory SET job_id=NULL WHERE job_id=?",k));d.put("JobSelectedStepCleared",del("UPDATE Job SET selected_job_step_id=NULL WHERE job_id=?",k));d.put("JobStep",del("DELETE s FROM JobStep s JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",k));d.put("JobTask",del("DELETE FROM JobTask WHERE job_id=?",k));d.put("Job",del("DELETE FROM Job WHERE job_id=?",k));return new HardDeleteResponse(id,"Job",Map.copyOf(d));}
 private long alerts(byte[]k){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM Alert a JOIN JobStep s ON a.job_step_id=s.job_step_id JOIN JobTask t ON s.job_task_id=t.job_task_id WHERE t.job_id=?",Long.class,k);return n==null?0:n;}private long openMappings(byte[]k){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM MappingSession WHERE job_id=? AND potentially_open=TRUE",Long.class,k);return n==null?0:n;}private long count(String t,String c,byte[]k){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+t+"` WHERE `"+c+"`=?",Long.class,k);return n==null?0:n;}private long countJoin(String a,String b,String ac,String bc,byte[]k){if(k==null)return 0;Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+a+"` x JOIN `"+b+"` y ON x.`"+ac+"`=y.`"+(b.equals("JobTask")?"job_task_id":ac)+"` WHERE y.`"+bc+"`=?",Long.class,k);return n==null?0:n;}private long del(String q,byte[]k){return jdbc.update(q,k);}private String status(byte[]k,UUID id){String s=jdbc.queryForObject("SELECT status FROM Job WHERE job_id=?",String.class,k);if(s==null)throw new ResourceNotFoundException("Job not found: "+id);return s;}private void lock(byte[]k,UUID id){if(jdbc.query("SELECT job_id FROM Job WHERE job_id=? FOR UPDATE",(r,n)->r.getBytes(1),k).isEmpty())throw new ResourceNotFoundException("Job not found: "+id);}private static byte[]key(UUID id){return ByteBuffer.allocate(16).putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).array();}}
